data.value:
erDiagram
    TENANT ||--o{ LOCATION : owns
    LOCATION ||--o{ SENSOR : has
    SENSOR_TYPE ||--o{ SENSOR : classifies
    SENSOR ||--o{ READING : produces
    TENANT {
        guid id
        string name
    }
    LOCATION {
        guid id
        guid tenant_id
        string name "unique per tenant"
    }
    SENSOR {
        guid id
        guid tenant_id
        string name
        string external_id "links incoming data"
        bool is_active
    }
    SENSOR_TYPE {
        int id
        string code "e.g. air_temperature"
        string unit "°C, %, ppm …"
    }
    READING {
        long id
        decimal value
        datetime measured_at
        datetime received_at
    }
